import{_ as e,c as o,o as t,ag as i}from"./chunks/framework.DfL_BkQ-.js";const g=JSON.parse('{"title":"安裝","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/installation.md","filePath":"zh-TW/guide/installation.md","lastUpdated":1791311600000}'),r={name:"zh-TW/guide/installation.md"};function l(n,a,s,d,h,c){return t(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to &quot;安裝&quot;">​</a></h1><p>nPlyr 來自同一個 Xcode 工程的兩個 target：</p><ul><li><strong><code>nPlyr</code></strong>——macOS 應用程式。</li><li><strong><code>nPlyrIOS</code></strong>——iOS / iPadOS 應用程式。</li></ul><p>兩者共用同一套播放核心與規則引擎。</p><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><h3 id="mac-app-store-推薦" tabindex="-1">Mac App Store（推薦） <a class="header-anchor" href="#mac-app-store-推薦" aria-label="Permalink to &quot;Mac App Store（推薦）&quot;">​</a></h3><ol><li>打開 <strong>Mac App Store</strong>，搜尋 <strong>nPlyr</strong>，或使用<a href="/zh-TW/">首頁</a>上的徽章。</li><li>點擊 <strong>取得</strong>，等待下載完成。</li><li>從 Dock 或啟動台啟動 nPlyr。</li></ol><p>Mac App Store 版本經過沙盒化並由 Apple 簽署，因此無需額外設定。</p><h3 id="側載-開發-testflight" tabindex="-1">側載（開發 / TestFlight） <a class="header-anchor" href="#側載-開發-testflight" aria-label="Permalink to &quot;側載（開發 / TestFlight）&quot;">​</a></h3><p>如果你從原始碼建構，請打開 <code>nPlyr.xcodeproj</code>，選擇 <strong><code>nPlyr</code></strong> scheme，並在「My Mac」上執行。開發簽署建構在首次使用瀏覽器或下載功能時，可能會提示你授予<a href="/zh-TW/guide/permissions.html">權限</a>中描述的權限。</p><h2 id="ios-ipados" tabindex="-1">iOS / iPadOS <a class="header-anchor" href="#ios-ipados" aria-label="Permalink to &quot;iOS / iPadOS&quot;">​</a></h2><h3 id="app-store" tabindex="-1">App Store <a class="header-anchor" href="#app-store" aria-label="Permalink to &quot;App Store&quot;">​</a></h3><p>在 iOS App Store 中搜尋 <strong>nPlyr</strong> 並安裝。同一個帳號可在兩個平台上解鎖小程式功能。</p><h3 id="從原始碼建構" tabindex="-1">從原始碼建構 <a class="header-anchor" href="#從原始碼建構" aria-label="Permalink to &quot;從原始碼建構&quot;">​</a></h3><ol><li>打開 <code>nPlyr.xcodeproj</code> 並選擇 <strong><code>nPlyrIOS</code></strong> scheme。</li><li>選擇一個模擬器或已連接的裝置（iOS 16+）。</li><li>執行。在實體裝置上，你需要在 Signing &amp; Capabilities 中設定一個開發團隊。</li></ol><blockquote><p>iOS 建構與 macOS 使用同一套共享原始碼；只有少量平台膠水檔案不同。沒有獨立的 <code>ffmpeg</code> 依賴。</p></blockquote><h2 id="首次啟動" tabindex="-1">首次啟動 <a class="header-anchor" href="#首次啟動" aria-label="Permalink to &quot;首次啟動&quot;">​</a></h2><p>首次啟動時，nPlyr 會：</p><ul><li>請求它所需的權限（請參閱<a href="/zh-TW/guide/permissions.html">權限</a>），</li><li>在使用者資料容器中建立本機媒體庫，</li><li>預設使用你的系統語言（可隨時在<a href="/zh-TW/guide/settings.html">設定</a>中切換）。</li></ul><p>如果安裝後某些行為不符合預期，請跳轉到<a href="/zh-TW/guide/troubleshooting.html">疑難排解</a>。</p>',20)])])}const m=e(r,[["render",l]]);export{g as __pageData,m as default};
